import os
import torch
import random
import numpy as np


class Config:
    # ==========================================
    # 1. Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_8"
    SUBMISSION_DIR = "./submission"

    # Input Files
    TRAIN_CSV = os.path.join(INPUT_DIR, "train.csv")
    TEST_CSV = os.path.join(INPUT_DIR, "test.csv")
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Metadata Files (Generated by previous steps)
    TRAIN_META = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_META = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_META = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output Files
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")
    MODEL_CHECKPOINT = os.path.join(WORKING_DIR, "best_model.pth")

    # Cache Files (Parquet format preferred over pickle for security/speed)
    TRAIN_CACHE = os.path.join(WORKING_DIR, "train_features.parquet")
    VAL_CACHE = os.path.join(WORKING_DIR, "val_features.parquet")
    TEST_CACHE = os.path.join(WORKING_DIR, "test_features.parquet")

    # ==========================================
    # 2. Data Configuration
    # ==========================================
    DEBUG = False  # Set to True to train on a small subset
    DEBUG_SIZE = 2000  # Number of breaths to use in debug mode

    NUM_WORKERS = 4  # Number of DataLoader workers
    PIN_MEMORY = True  # Pin memory for faster GPU transfer

    # Feature Engineering Specs
    # Features: [time_step, u_in, u_out, R, C, dt, u_in_cumsum, R_u_in, u_in_cumsum_C,
    #            u_in_lag1..4, u_in_diff1..2, u_out_lag1..2]
    # Estimated dimensionality for the GI-DBiLSTM input
    INPUT_DIM = 18
    SEQ_LEN = 80  # Fixed sequence length for ventilator breaths

    # ==========================================
    # 3. Model Hyperparameters (GI-DBiLSTM)
    # ==========================================
    # Architecture: Gated-Injection Deep Bidirectional LSTM
    LSTM_HIDDEN_SIZE = 512
    LSTM_LAYERS = 4
    GLU_DIM = 256  # Dimension for the Gated Linear Unit projection
    BIDIRECTIONAL = True

    # Regularization
    # Note: GLU projection must be deterministic (Dropout=0.0) per strategy
    GLU_DROPOUT = 0.0
    LSTM_DROPOUT = 0.1  # Dropout applied between LSTM layers

    # ==========================================
    # 4. Training Configuration
    # ==========================================
    SEED = 42
    EPOCHS = 150  # Long-Tail Convergence Protocol
    BATCH_SIZE = 256  # Optimized for A100-40GB

    # Optimizer (AdamW)
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2
    MAX_GRAD_NORM = 1.0  # Gradient clipping for LSTM stability

    # Scheduler (Cosine Annealing)
    T_MAX = 150
    ETA_MIN = 1e-5

    # Weighted L1 Loss Configuration
    LOSS_INSPIRATORY_WEIGHT = 1.0
    LOSS_EXPIRATORY_WEIGHT = 0.1

    # Hardware
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Initializes the environment:
        1. Creates necessary working and submission directories.
        2. Sets random seeds for reproducibility.
        """
        # Create directories
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set reproducible seeds
        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(cls.SEED)

        # Enforce deterministic algorithms where possible
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

        print(f"Config setup complete. Working dir: {cls.WORKING_DIR}")
        print(f"Device: {cls.DEVICE}")
